jest.mock("@paypal/paypal-js",(()=>({loadScript:jest.fn()})));import{h}from"@stencil/core";import{newSpecPage}from"@stencil/core/testing";import{loadScript}from"@paypal/paypal-js";import{ScPaypalButtons}from"../paypal-buttons";import{flush,makePaypal}from"./helpers";const loadScriptMock=loadScript,makePage=async(e={id:"checkout_1",currency:"usd",updated_at:1},t=["paypal","card"])=>newSpecPage({components:[ScPaypalButtons],template:()=>h("sc-paypal-buttons",{clientId:"client-id",merchantId:"merchant-id",buttons:t,order:e})}),skeleton=e=>e.root.shadowRoot.querySelector("sc-skeleton");describe("paypal-buttons",(()=>{beforeEach((()=>{jest.clearAllMocks()})),it("renders",(async()=>{const e=await newSpecPage({components:[ScPaypalButtons],html:"<sc-paypal-buttons></sc-paypal-buttons>"});expect(e.root).toMatchSnapshot()})),it("does not tear down when the checkout updates without a currency or reusable change",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e);const t=await makePage();await flush(),await t.waitForChanges(),expect(loadScriptMock).toHaveBeenCalledTimes(1),e.buttons[0].config.onInit(),await t.waitForChanges(),expect(skeleton(t)).toBeNull(),t.root.order={id:"checkout_1",currency:"usd",updated_at:2},await t.waitForChanges(),await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(1),expect(skeleton(t)).toBeNull()})),it("does not tear down mid-payment when onApprove refreshes the checkout",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e);const t=await makePage({id:"checkout_1",currency:"usd",updated_at:1,reusable_payment_method_required:!1});await flush(),await t.waitForChanges(),e.buttons[0].config.onInit(),await t.waitForChanges(),t.root.order={id:"checkout_1",currency:"usd",updated_at:2},await t.waitForChanges(),await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(1),expect(skeleton(t)).toBeNull()})),it("re-bootstraps and shows the skeleton when the currency changes",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e);const t=await makePage();await flush(),await t.waitForChanges(),e.buttons[0].config.onInit(),await t.waitForChanges(),expect(skeleton(t)).toBeNull(),t.root.order={id:"checkout_1",currency:"eur",updated_at:2},await t.waitForChanges(),expect(skeleton(t)).not.toBeNull(),await flush(),await t.waitForChanges(),expect(loadScriptMock).toHaveBeenCalledTimes(2),expect(e.Buttons).toHaveBeenCalledTimes(4)})),it("re-bootstraps when the reusable payment method requirement changes",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e);const t=await makePage({id:"checkout_1",currency:"usd",reusable_payment_method_required:!1});await flush(),await t.waitForChanges(),expect(e.buttons[0].config.createOrder).toBeDefined(),t.root.order={id:"checkout_1",currency:"usd",reusable_payment_method_required:!0},await t.waitForChanges(),await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(2),expect(e.buttons[2].config.createBillingAgreement).toBeDefined()})),it("ignores a superseded bootstrap",(async()=>{const e=makePaypal();let t,a;loadScriptMock.mockReturnValueOnce(new Promise((e=>t=e))).mockReturnValueOnce(new Promise((e=>a=e)));const o=await makePage();o.root.order={id:"checkout_1",currency:"eur",updated_at:2},await o.waitForChanges(),a(e),await flush(),expect(e.Buttons).toHaveBeenCalledTimes(2),t(e),await flush(),expect(e.Buttons).toHaveBeenCalledTimes(2)})),it("only bootstraps the funding sources in `buttons`",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e),await makePage({id:"checkout_1",currency:"usd"},["paypal"]),await flush(),expect(e.Buttons).toHaveBeenCalledTimes(1),expect(e.buttons[0].config.fundingSource).toBe("paypal")})),it("re-bootstraps when the `buttons` contents change, not when only the reference does",(async()=>{const e=makePaypal();loadScriptMock.mockResolvedValue(e);const t=await makePage({id:"checkout_1",currency:"usd"},["paypal"]);await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(1),t.root.buttons=["card"],await t.waitForChanges(),await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(2),expect(e.buttons[1].config.fundingSource).toBe("card"),t.root.buttons=["card"],await t.waitForChanges(),await flush(),expect(loadScriptMock).toHaveBeenCalledTimes(2)}))}));